using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Searches for a given quote in a text. Returns found quote start position in UTF-16 code units. Returns a 404 error if the quote is not found. Can be called synchronously
    /// </summary>
    public Task<TdLib.TdApi.Objects.FoundPosition> SearchQuoteAsync(FormattedText text = default, FormattedText quote = default, int quotePosition = default)
    {

           using var activity =  StartCallActivity("SearchQuoteAsync", typeof(SearchQuote).FullName ?? "SearchQuoteAsync");

           try
           {
             return client.SearchQuoteAsync(text, quote, quotePosition);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
